typeScripts.javaScript:
import { LocalRoutines } from '../interface';
import { handleMutationResponse, resolveCodeByReference, resolveImportedReference } from '../../scripts/helper';
import { LOG } from '@eip/core';
export function process(invocation, self) {
    const context = invocation.processors.importCases.input.context;
    const crmCase = invocation.processors.iterationCases.element.value;
    if (resolveImportedReference(context, crmCase.id)) {
        LOG.warn('Update operation not supported');
    }
    else if (!resolveCodeByReference(context, 'Process', crmCase.codeProcess.code)) {
        LOG.warn('Unknow process {}. Skipping...', crmCase.codeProcess.code);
    }
    else {
        handleMutationResponse(context, 'case', crmCase, LocalRoutines.createCase({ context, crmCase }));
    }
}

typeScripts.typeScript:
import { Self } from './definition';
import { Invocation, LocalRoutines } from '../interface';
import { handleMutationResponse, resolveCodeByReference, resolveImportedReference } from '../../scripts/helper';
import { LOG } from '@eip/core';
import { IContext, CrmCase } from '../../scripts/data_types';

export function process(invocation: Invocation, self: Self) {
  const context: IContext = invocation.processors.importCases.input.context; 
  const crmCase: CrmCase = invocation.processors.iterationCases.element.value;

  if (resolveImportedReference(context, crmCase.id)) {
    LOG.warn('Update operation not supported');
  } else if (!resolveCodeByReference(context, 'Process', crmCase.codeProcess.code)) {
    LOG.warn('Unknow process {}. Skipping...', crmCase.codeProcess.code);
  } else {
    handleMutationResponse(context, 'case', crmCase, LocalRoutines.createCase({context, crmCase}));
  }
}

