import { Self } from './definition';
import { Invocation } from '../interface';
import { Codes } from '@eip/crm-core';
import { CrmCaseCommunicationType, CrmCaseInput, CrmCaseItem, CrmCaseMemoType, CrmCaseProtocol, CrmCaseSlaHistory, CrmCaseStep, CrmCaseStepHistory, CrmCaseStepOutput, Mutations } from '@eip/crm-mutation';
import { CaseStep, CaseStepHistory, CrmCase, CrmCommunications, CustomerRef, ICaseLinkedItem, IContext } from '../../scripts/data_types';
import { createRefKey, resolveCodeByReference, resolveCrmBusinessByReference, resolveCrmCaseByReference, resolveCrmCaseStepByReference, resolveCrmCommunicationByReference, resolveCrmCustomerByReference, resolveCrmItemKeyByReference, resolveCrmServiceLine, resolveCrmTaskByReference, resolveCrmUserByReference } from '../../scripts/helper';
import { timeShift } from '../../scripts/timeshift';
import { LOG } from '@eip/core';
import { createLayerCrmCaseImportMutationAttributes } from '../../scripts/layer_import';
import { createProjectCrmCaseImportMutationAttributes } from '../../scripts/project_import';

export function process(invocation: Invocation, self: Self) {
  const mutations = [];
  const context: IContext = invocation.processors.createCase.input.context;
  const crmCase: CrmCase = invocation.processors.createCase.input.crmCase;

  mutations.push(handleCrmCase(context, crmCase));

  if (mutations.filter(Boolean).length > 0) {
    self.withOutlet('hasMutations');
  } else {
    self.withOutlet('noMutations');
  }
  return mutations.filter(Boolean);
}

function handleCrmCase(context: IContext, crmCase: CrmCase) {
  return Mutations.create('CrmCaseImport', createCaseImportMutationAttributes(context, crmCase));
}

function createCaseImportMutationAttributes(context: IContext, crmCase: CrmCase) {
  var crm = createCrmCaseImportMutationAttributes(context, crmCase);
  var layer = createLayerCrmCaseImportMutationAttributes(context, crmCase)
  var project = createProjectCrmCaseImportMutationAttributes(context, crmCase)
  return Object.assign({}, crm, layer, project);
}

function createCrmCaseImportMutationAttributes(context: IContext, crmCase: CrmCase) {
  let triggeringCaseStepRef = null;
  if (crmCase.triggeringCaseStep?.id) {
    triggeringCaseStepRef = resolveCrmCaseStepByReference(context, crmCase.triggeringCaseStep?.id);
    if (!triggeringCaseStepRef) {
      // assume case step of current import
      triggeringCaseStepRef = 'ref:'+ crmCase.triggeringCaseStep?.id;
    }
  }

  return {
    process: resolveCodeByReference(context, 'Process', crmCase.codeProcess.code),
    caseNo: crmCase.no,
    triggeringCaseStepKeyRef: triggeringCaseStepRef,
    startDate: timeShift(context, crmCase.openDate, true),
    endDate: timeShift(context, crmCase.closeDate, true),
    createItemKeyRef: resolveCrmItemKeyByReference(context, crmCase.createdBy),
    status: resolveCodeByReference(context, 'CommunicationStatus', crmCase.status),
    finishReason: resolveCodeByReference(context, 'FinishReason', crmCase.finishReason),
    startCommunicationKeyRef: resolveCrmCommunicationByReference(context, crmCase.startCommunication.globalKey),
    partitions: crmCase.partitions?.map(p => resolveCodeByReference(context, 'Partition', p)),
    reminderDate: timeShift(context, crmCase.reminderDate), // future date allowed
    escalationDate: timeShift(context, crmCase.escalationDate), // future date allowed
    escalationResponsibleType: resolveCodeByReference(context, 'ResponsibleType', crmCase.escalationResponsibleType),
    escalationResponsibleTeam: resolveCodeByReference(context, 'Team', crmCase.escalationResponsibleTeam?.team),
    escalationResponsibleTeamRole: resolveCodeByReference(context, 'TeamRole', crmCase.escalationResponsibleTeamRole),
    overdueDate: timeShift(context, crmCase.overdueDate), // future date allowed
    overdueResponsibleType: resolveCodeByReference(context, 'ResponsibleType', crmCase.overdueResponsibleType),
    overdueResponsibleTeam: resolveCodeByReference(context, 'Team', crmCase.overdueResponsibleTeam?.team),
    overdueResponsibleTeamRole: resolveCodeByReference(context, 'TeamRole', crmCase.overdueResponsibleTeamRole),
    serviceLineKeyRef: resolveCrmServiceLine(context, crmCase.serviceLine?.globalKey),
    lastSendStatus: resolveCodeByReference(context, 'CommunicationStatus', crmCase.lastSendStatus),
    caseInputs: createCaseInputs(context, crmCase),
    caseSteps: createCaseSteps(context, crmCase),
    caseItems: createCaseItems(context, crmCase),
    caseStepHistories: createCaseStepHistories(context, crmCase),
    caseProtocols: createCaseProtocols(context, crmCase),
    memos: createMemos(context, crmCase),
    communications: createCommunication(context, crmCase),
    caseSlaHistories: createSlaHistory(context, crmCase),
    // case step history not supported for the moment
    mutationRef: createRefKey(context, crmCase)
  };
}


function createSlaHistory(context: IContext, crmCase: CrmCase) : CrmCaseSlaHistory[] {
  return crmCase.caseSlaHistories?.map(slaHistory => {
    return {
      changeDate: timeShift(context, slaHistory.changeDate, true),
      escalationDate: timeShift(context, slaHistory.escalationDate), // future date allowed
      escalationPrevDate: timeShift(context, slaHistory.escalationPrevDate), // future date allowed
      overdueDate: timeShift(context, slaHistory.overdueDate), // future date allowed
      overduePrevDate: timeShift(context, slaHistory.overduePrevDate), // future date allowed
      reminderDate: timeShift(context, slaHistory.remindDate), // future date allowed
      slaAdjournment: slaHistory.slaAdjournment
    };
  });
}

function createCommunication(context: IContext, crmCase: CrmCase) : CrmCaseCommunicationType[]{
   return crmCase.caseLinkedCommunications?.map(linkedCommunication => linkedCommunication.communication).map(communication => {
    const contextCustomer = getContextCustomer(context, communication);

    let caseStepKeyRef = null;
    if (communication.caseStep?.id) {
      caseStepKeyRef = resolveCrmCaseStepByReference(context, communication.caseStep.id);
      if (!caseStepKeyRef) {
        // assume case step of current import
        caseStepKeyRef = 'ref:'+ communication.caseStep.id;
      }
    }

    return {
      channel: resolveCodeByReference(context, 'MessageChannel', communication.channel),
      incoming: communication.incoming,
      subject: communication.subject,
      primaryCustomerKeyRef: resolveCrmCustomerByReference(context, communication.primaryCustomer?.globalKey),
      contextCustomerKeyRef: resolveCrmCustomerByReference(context, contextCustomer?.globalKey),
      emotion: resolveCodeByReference(context, 'Emotion', communication.emotion),
      endDate: timeShift(context, communication.endDate, true),
      language: resolveCodeByReference(context, 'Language', communication.language),
      location: communication.location,
      partitions: communication.partitions?.map(p => resolveCodeByReference(context, 'Partition', p)),
      reactionGroup: resolveCodeByReference(context, 'CommunicationReactionGroup', communication.reactionGroup),
      remark: communication.remark,
      startDate: timeShift(context, communication.startDate, true),
      status: resolveCodeByReference(context, 'CommunicationStatus', communication.status),
      caseStepKeyRef: caseStepKeyRef,
      mutationRef: createRefKey(context, communication)
    };
  }); 
}

function getContextCustomer(context: IContext, communication: CrmCommunications): CustomerRef {
  if (!communication.primaryCustomer || !communication.primaryOrContextCustomer) {
    return null;
  }
  if (communication.primaryCustomer.globalKey !== communication.primaryOrContextCustomer.globalKey) {
    return communication.primaryOrContextCustomer;
  }
  else {
    return null;
  }
}

function createMemos(context: IContext, crmCase: CrmCase) : CrmCaseMemoType[] {
  return crmCase.memos?.map(memo => {
    return {
      subject: memo.subject,
      content: memo.content,
      createdOn: timeShift(context, memo.createdOn, true),
      createdByUserKeyRef: resolveCrmUserByReference(context, memo.createdBy?.globalKey),
      caseStepKeyRef: 'ref:'+createRefKey(context, memo.caseStep),
      mutationRef: createRefKey(context, memo)
    };
  });
}

function createCaseProtocols(context: IContext, crmCase: CrmCase): CrmCaseProtocol[] {
  return crmCase.caseProtocols.map(protocol => {
    let stepKeyRef = null;
    if (protocol.caseStep?.id) {
      stepKeyRef = resolveCrmCaseStepByReference(context, protocol.caseStep?.id);
      if (!stepKeyRef) {
        // assume case step of current import
        stepKeyRef = 'ref:'+ createRefKey(context, protocol.caseStep);
      }
    }
    let itemKeyRef = null;
    if (protocol.itemEntityKey) {
      itemKeyRef = resolveCrmItemKeyByReference(context, protocol.itemEntityKey);
      if (!itemKeyRef) {
         // assume ref of current import
        itemKeyRef = 'ref:'+ protocol.itemEntityKey;
      }
    }
    let modifiedByKeyRef = null;
    if (protocol.modifiedBy) {
      modifiedByKeyRef = resolveCrmItemKeyByReference(context, protocol.modifiedBy);
      if (!modifiedByKeyRef) {
        LOG.warn('Skipping protocoll {} due to unresolved modifiedBy.', protocol);
        // unresolved. skipping protocoll
        return null;
      }
    }
    return {
      date: timeShift(context, protocol.date, true),
      itemEvent: resolveCodeByReference(context, 'ItemEvent', protocol.itemEvent),
      itemKeyRef: itemKeyRef,
      modifiedByKeyRef: modifiedByKeyRef,
      stepKeyRef: stepKeyRef,
      type: resolveCodeByReference(context, 'CaseLogType', protocol.type)
    };
  }).filter(Boolean);
}


function createCaseItems(context: IContext, crmCase: CrmCase) {
    return [
    ...createCaseItem(context, crmCase, (crmCase) => crmCase.caseLinkedBusinesses, (item => resolveCrmBusinessByReference(context, createCaseItemKey(item['business'])))),
    ...createCaseItem(context, crmCase, (crmCase) => crmCase.caseLinkedCommunications, (item => resolveCrmBusinessByReference(context, createCaseItemKey(item['communcation'])))),
    ...createCaseItem(context, crmCase, (crmCase) => crmCase.caseLinkedCustomers, (item => resolveCrmCustomerByReference(context, createCaseItemKey(item['customer'])))),
    ...createCaseItem(context, crmCase, (crmCase) => crmCase.caseLinkedTasks, (item => resolveCrmTaskByReference(context, createCaseItemKey(item['task']))))];
}

function createCaseItemKey(item) {
  if (!item) {
    return null;
  }
  if (item.globalKey) {
    return item.globalKey;
  }
  else {
    return item.id;
  }
}

function createCaseItem(context: IContext, crmCase: CrmCase, itemFunc: (item: CrmCase) => ICaseLinkedItem[], itemKeyFunc: (item: ICaseLinkedItem) => string): CrmCaseItem[] {
  if (!itemFunc(crmCase)) {
    return [];
  }
  return itemFunc(crmCase).map(item => {
    let caseStepKeyRef = null;
    if (item.caseStep?.id) {
      caseStepKeyRef = resolveCrmCaseStepByReference(context, item.caseStep?.id);
      if (!caseStepKeyRef) {
        // assume case step of current import
        caseStepKeyRef = 'ref:'+ item.caseStep?.id;
      }
    }
    return {
      caseStepKeyRef: caseStepKeyRef,
      itemKeyRef: itemKeyFunc(item),
      linkType: resolveCodeByReference(context, 'CaseItemLinkType', item.linkType)
    };
  });
}

function createCaseInputs(context: IContext, crmCase: CrmCase) {
  return [
    //createCaseInput(Codes.ProcessInput.Action, 128301, crmCase), not supported
    createCaseInput(context, Codes.ProcessInput.Business, 128302, crmCase, (id =>  resolveCrmBusinessByReference(context, id))),
    // createCaseInput(Codes.ProcessInput.Campaign, 128303, crmCase, null), // not supported
    createCaseInput(context, Codes.ProcessInput.Communication, 128304, crmCase, (id =>  resolveCrmCommunicationByReference(context, id))),
    createCaseInput(context, Codes.ProcessInput.ContextCustomer, 128236, crmCase, (id => resolveCrmCustomerByReference(context, id))),
    createCaseInput(context, Codes.ProcessInput.CurrentCase, 128212, crmCase, (id => resolveCrmCaseByReference(context, id))),
    createCaseInput(context, Codes.ProcessInput.CurrentCommunicationCaseFrame, 128306, crmCase, (id => resolveCrmCommunicationByReference(context, id))),
    // createCaseInput(Codes.ProcessInput.InsignSession, 211988, crmCase), // not supported
    // createCaseInput(Codes.ProcessInput.Knowledge, 128305, crmCase, null), // not supported
    createCaseInput(context, Codes.ProcessInput.PrimaryCustomer, 128213, crmCase, (id => resolveCrmCustomerByReference(context, id))),
    // createCaseInput(Codes.ProcessInput.SocialMediaItem, 143408, crmCase), // not supported
    // createCaseInput(Codes.ProcessInput.SocialMediaPlatformType, 144763, crmCase), // not supported
    createCaseInput(context, Codes.ProcessInput.Task, 128307, crmCase, (id => resolveCrmTaskByReference(context, id))),
    // createCaseInput(Codes.ProcessInput.Ticket, 128308, crmCase, null), // not supported
    createCaseInput(context, Codes.ProcessInput.TriggeringCase, 150290, crmCase, (id => resolveCrmCaseStepByReference(context, id)))]
    .filter(Boolean);
}

function createCaseInput(context: IContext, caseInput: string, inputCodeId: number, crmCase: CrmCase, resolver: (globalKey: string) => string): CrmCaseInput {
  if (!crmCase['processInput-' + inputCodeId]) {
    return null;
  }
  var ref = resolveCrmItemKeyByReference(context, crmCase['processInput-' + inputCodeId]?.id);
  if (!ref && crmCase['processInput-' + inputCodeId]?.globalKey) {
    ref = resolver(crmCase['processInput-' + inputCodeId]?.globalKey);
  }
  if (!ref) {
    return null;
  }
  return {
    caseInput: caseInput,
    caseInputItemKeyRef: ref
  };
}

function createCaseSteps(context: IContext, crmCase: CrmCase) : CrmCaseStep[] {
  return crmCase.caseSteps.sort((a, b) => Date.parse(a.createDate?.toString()) - Date.parse(b.createDate?.toString())).map(step => {
    let caseStepOutputs: CrmCaseStepOutput[] = step.caseStepOutputs.map(output => {
      let itemEntityKeyRef = null;
      if (output.itemEntityKey) {
        itemEntityKeyRef = resolveCrmItemKeyByReference(context, output.itemEntityKey);
        if (!itemEntityKeyRef) {
          // assume current mutation
          itemEntityKeyRef = 'ref:'+ output.itemEntityKey;
        }
      }
      return {
        parameter: output.outputParam,
        itemKeyRef: itemEntityKeyRef,
        text: output.valueLob,
        date: timeShift(context, output.valueDate, true),
        decimal: output.valueDecimal,
        filename: output.valueFilename,
        content: output.valueContent
      };
    });

    let copySourceCaseStepKeyRef = null;
    if (step.copySourceStep?.id) {
      copySourceCaseStepKeyRef = resolveCrmCaseStepByReference(context, step.copySourceStep.id);
      if (!copySourceCaseStepKeyRef) {
        // assume current mutation
        copySourceCaseStepKeyRef = 'ref:'+ step.copySourceStep.id;
      }
    }

    return {
      step: resolveCodeByReference(context, 'Process', step.step),
      stepDefinitionKeyRef: step.stepDefinition,
      createDate: timeShift(context, step.createDate, true),
      endDate: timeShift(context, step.endDate, true),
      plannedDate: timeShift(context, step.plannedDate, true),
      plannedStartDate: timeShift(context, step.plannedStartDate, true),
      startDate: timeShift(context, step.startDate, true),
      copySourceCaseStepKeyRef: copySourceCaseStepKeyRef,
      createItemKeyRef: resolveCrmItemKeyByReference(context, step.createdBy),
      endItemKeyRef: resolveCrmUserByReference(context, step.endUser?.globalKey),
      responsibleAdvisor: resolveCrmUserByReference(context, step.responsibleAdvisor?.globalKey),
      responsibleTeamRole: resolveCodeByReference(context, 'TeamRole', step.responsibleTeamRole),
      responsibleTeam: resolveCodeByReference(context, 'Team', step.responsibleTeam?.team),
      responsibleType:  resolveCodeByReference(context, 'ResponsibleType', step.responsibleType),
      responsibleUserKeyRef: resolveCrmUserByReference(context, step.responsibleUser?.globalKey),
      stepGroup: step.stepGroup,
      workingTimeMillis: step.workingTimeInMilliseconds,
      outputs: caseStepOutputs,
      mutationRef: createRefKey(context, step)
    };
  });
}

function createCaseStepHistories(context: IContext, crmCase: CrmCase) : CrmCaseStepHistory[] {
  let  stepHistories: CrmCaseStepHistory[] = [];
  crmCase?.caseSteps?.forEach(step => step.caseStepHistories?.forEach(history => stepHistories.push(createCaseStepHistory(context, step, history))));
  return stepHistories.filter(Boolean);
}

function createCaseStepHistory(context: IContext, crmCaseStep: CaseStep, caseStepHistory: CaseStepHistory) : CrmCaseStepHistory {
  if (!caseStepHistory) {
    return null;
  }
  return {
    // required
    stepKeyRef: 'ref:'+createRefKey(context, crmCaseStep),
    type: resolveCodeByReference(context, 'CaseStepHistoryType', caseStepHistory.type),
    responsibleType: resolveCodeByReference(context, 'ResponsibleType', caseStepHistory.responsibleType),
    // optional
    responsibleTeam: resolveCodeByReference(context, 'Team', caseStepHistory.responsibleTeam?.team),
    responsibleTeamRole: resolveCodeByReference(context, 'TeamRole', caseStepHistory.responsibleTeamRole),
    responsibleUserKeyRef: resolveCrmUserByReference(context, caseStepHistory.responsibleUser?.globalKey),
    responsibleAdvisor:  resolveCodeByReference(context, 'Advisor', caseStepHistory.responsibleAdvisor),
    createUserKeyRef: resolveCrmUserByReference(context, caseStepHistory.createUser?.globalKey),
    startDate: caseStepHistory.startDate,
    endDate: caseStepHistory.endDate,
    mutationRef: createRefKey(context, caseStepHistory)
  }
}

