import { Self } from './definition';
import { Invocation } from '../interface';
import { LOG, ProcessorTypes } from '@eip/core';
import { Codes } from '@eip/crm-core';
import { Mutations } from '@eip/crm-mutation';
import { createLayerCustomerElectronicAddressMutationAttributes, createLayerCustomerInterestMutationAttributes, createLayerCustomerMutationAttributes, createLayerCustomerPhysicalAddressMutationAttributes, createLayerUserMutationAttributes, createLayerUserProfileMutationAttributes } from '../../scripts/layer_import';
import { createProjectCustomerMutationAttributes, createProjectCustomerElectronicAddressMutationAttributes, createProjectCustomerPhysicalAddressMutationAttributes, createProjectCustomerInterestMutationAttributes, createProjectUserMutationAttributes, createProjectUserDefaultPassword, createProjectUserProfileMutationAttributes, createProjectCustomerIdentityDefaultPassword, createProjectCustomerIdentityTwoFactorDefaultPassword, createProjectCustomerIdentitySecondFactorDefault, createProjectUserDefaultCtiProviderService } from '../../scripts/project_import';
import { handleDocument } from '../../scripts/crm_import';
import { timeShift } from '../../scripts/timeshift';
import { AddressChannelOptIn, CrmCustomers, CustomerIdentity, CustomerInterest, CustomerScore, ElectronicAddresses, IContext, PhysicalAddresses, User, UserProfiles } from '../../scripts/data_types';
import { createRefKey, resolveCodeByReference, resolveCrmCustomerByReference } from '../../scripts/helper';

export function process(invocation: Invocation, self: Self) {
  const mutations = [];
  const context: IContext = invocation.processors.createCustomer.input.context;
  const customer: CrmCustomers = invocation.processors.createCustomer.input.customer;

  // skip protected users
  if (customer.user?.username === 'system' || customer.user?.username === 'administrator' || customer.user?.username === 'admin') {
    self.withOutlet('noMutations');
    return mutations;
  }

  // customer
  mutations.push(handleCustomer(context, customer));
  const customerRef = createRefKey(context, customer);

  // customer interest
  customer.customerInterests?.forEach(i => mutations.push(handleCustomerInterest(context, i, customer, customerRef)));

  // user and user roles
  if (!!(customer.user?.username)) {
    // user
    mutations.push(handleUser(context, customer.user, customer, customerRef));
    // roles
    customer.user.userProfiles?.forEach(up => mutations.push(handleUserProfile(context, up, customer, customerRef, customer.user.globalKey)));
  }

  // documents
  customer.documents.map(d => handleDocument(context, customerRef, d.globalKey)).filter(Boolean).forEach(m => mutations.push(m));

  if (mutations.filter(Boolean).length > 0) {
    self.withOutlet('hasMutations');
  }
  else {
    self.withOutlet('noMutations');
  }
  return mutations.filter(Boolean);
}

// customer

function handleCustomer(context: IContext, customer: CrmCustomers) {
  return Mutations.create('CrmCustomerCreate', createCustomerMutationAttributes(context, customer))
}

function createCustomerMutationAttributes(context: IContext, customer: CrmCustomers) {
  var crm = createCrmCustomerMutationAttributes(context, customer);
  var layer = createLayerCustomerMutationAttributes(context, customer);
  var project = createProjectCustomerMutationAttributes(context, customer);
  return Object.assign({}, crm, layer, project);
}

function createCrmCustomerMutationAttributes(context: IContext, customer: CrmCustomers) {
  return {
    // required
    gender: resolveCodeByReference(context, 'CustomerGender', customer.gender),
    name1: customer.name1,
    type: resolveCodeByReference(context, 'CustomerType', customer.type),
    // optional
    active: customer.active,
    //advisors: [], // advisor import done later to ensure all users are created
    birthdate: timeShift(context, customer.birthdate),
    electronicAddresses: customer.electronicAddresses?.sort((a, b) => (a.preferred == b.preferred) ? 0 : a.preferred ? -1 : 1)
      .map(a => createCustomerElectronicAddressMutationAttributes(context, a, customer, customer.globalKey)),
    financialFigures: customer.customerFinancialFigures?.map(f => { return { year: f.year, budget: f.budget?.amount, potentialTurnover: f.potential?.amount }; }),
    identities: customer.customerIdentities?.map(i => createCustomerIdentityMutationAttributes(context, customer, i)).filter(Boolean),
    image: customer.image,
    language: resolveCodeByReference(context, 'Language', customer.language),
    name2: customer.name2,
    name3: customer.name3,
    no: customer.no,
    optIn: createCustomerOptInMutationAttributes(context, customer),
    partitions: customer.partitions.map(p => resolveCodeByReference(context, 'Partition', p)),
    physicalAddresses: customer.physicalAddresses?.sort((a, b) => (a.preferred == b.preferred) ? 0 : a.preferred ? -1 : 1)
      .map(a => createCustomerPhysicalAddressMutationAttributes(context, a, customer, customer.globalKey)),
    rating: resolveCodeByReference(context, 'CustomerRating', customer.rating),
    remark: customer.remark,
    scores: customer.customerScores?.map(cs => handleCustomerScore(context, cs)).filter(Boolean),
    segmentations: customer.segmentations ? customer.segmentations?.map(s => resolveCodeByReference(context, 'CustomerSegmentation', s.code)).filter(s => !!s) : [],
    shortName: customer.shortName,
    title: customer.title,
    useTitleInAddress: customer.useTitleInAddress,
    mutationRef: createRefKey(context, customer)
  };
}

// customer identity

function createCustomerIdentityMutationAttributes(context: IContext, customer: CrmCustomers, customerIdentity: CustomerIdentity) {
  if (!customerIdentity) {
    return null;
  }
  const customerIdentityType = resolveCodeByReference(context, 'CustomerIdentityType', customerIdentity.type);
  if (Codes.CustomerIdentityType.BsiOneFactor === customerIdentityType) {
    return createCustomerIdentityBsiOneFactorMutationAttributes(context, customer, customerIdentity);
  } else if (Codes.CustomerIdentityType.BsiTwoFactor === customerIdentityType) {
    return createCustomerIdentityBsiTwoFactorMutationAttributes(context, customer, customerIdentity);
  } else if (Codes.CustomerIdentityType.PortalOneFactor === customerIdentityType) {
    return createCustomerIdentityPortalOneFactorMutationAttributes(context, customer, customerIdentity);
  } else if (Codes.CustomerIdentityType.PortalTwoFactor === customerIdentityType) {
    return createCustomerIdentityPortalTwoFactorMutationAttributes(context, customer, customerIdentity);
  } else if (Codes.CustomerIdentityType.OpenIdConnect === customerIdentityType) {
    return createCustomerIdentityOpenIdConnectMutationAttributes(context, customer, customerIdentity);
  } else {
    LOG.error('Skipping unsupported customer identity type {}.', customerIdentity.type);
    return null;
  }
}

function createCustomerIdentityBsiOneFactorMutationAttributes(context: IContext, customer: CrmCustomers, customerIdentity: CustomerIdentity) {
  return {
    identityType: Codes.CustomerIdentityType.BsiOneFactor,
    userId: customerIdentity.userId,
    password: createProjectCustomerIdentityDefaultPassword(context, customer, customerIdentity),
    locked: customerIdentity.locked
  }
}

function createCustomerIdentityBsiTwoFactorMutationAttributes(context: IContext, customer: CrmCustomers, customerIdentity: CustomerIdentity) {
  const twoFactorType = resolveCodeByReference(context, 'TwoFactorType', customerIdentity.twoFactorType);
  return {
    identityType: Codes.CustomerIdentityType.BsiTwoFactor,
    userId: customerIdentity.userId,
    password: createProjectCustomerIdentityDefaultPassword(context, customer, customerIdentity),
    locked: customerIdentity.locked,
    twoFactorType: twoFactorType,
    twoFactorAddress: customerIdentity.twoFactorAddress,
    twoFactorSecret: (Codes.TwoFactorType.App === twoFactorType) ? createProjectCustomerIdentityTwoFactorDefaultPassword(context, customer, customerIdentity) : null
  }
}

function createCustomerIdentityPortalOneFactorMutationAttributes(context: IContext, customer: CrmCustomers, customerIdentity: CustomerIdentity) {
  return {
    identityType: Codes.CustomerIdentityType.PortalOneFactor,
    userId: customerIdentity.userId,
    password: createProjectCustomerIdentityDefaultPassword(context, customer, customerIdentity),
    locked: customerIdentity.locked
  }
}

function createCustomerIdentityPortalTwoFactorMutationAttributes(context: IContext, customer: CrmCustomers, customerIdentity: CustomerIdentity) {
  return {
    identityType: Codes.CustomerIdentityType.PortalTwoFactor,
    userId: customerIdentity.userId,
    password: createProjectCustomerIdentityDefaultPassword(context, customer, customerIdentity),
    locked: customerIdentity.locked,
    secondFactor: createProjectCustomerIdentitySecondFactorDefault(context, customer, customerIdentity),
  }
}

function createCustomerIdentityOpenIdConnectMutationAttributes(context: IContext, customer: CrmCustomers, customerIdentity: CustomerIdentity) {
  return {
    identityType: Codes.CustomerIdentityType.OpenIdConnect,
    userId: customerIdentity.userId,
    locked: customerIdentity.locked
  }
}

// opt in by address

function createCustomerOptInMutationAttributes(context: IContext, customer: CrmCustomers) {
  return {
    advertisingBlock: customer.advertisingBlockBlock,
    byCustomer: customer.advertisingBlockByCustomer,
    communicationKeyRef: null, // Not supported
    declineReason: customer.advertisingBlockReason,
    preferredMarketingChannel: resolveCodeByReference(context, 'AddressChannel', customer.preferredChannel),
    byAddress: createCustomerOptInByAddressesMutationAttributes(context, customer),
    byChannel: createCustomerOptInsByChannelsMutationAttributes(context, customer),
    byTopic: createCustomerOptInByTopicsMutationAttributes(context, customer)
  };
}

function createCustomerOptInByAddressesMutationAttributes(context: IContext, customer: CrmCustomers) {
  return [
    ...customer?.physicalAddresses?.map(address => createCustomerOptInByAddresseMutationAttributes(context, customer, address)),
    ...customer?.electronicAddresses?.map(address => createCustomerOptInByAddresseMutationAttributes(context, customer, address))
  ];
}

function createCustomerOptInByAddresseMutationAttributes(context: IContext, customer: CrmCustomers, address: PhysicalAddresses | ElectronicAddresses) {
  var crm = createCrmCustomerOptInByAddresseMutationAttributes(context, customer, address);
  var layer = {} // Not supported
  var project = {} // Not supported
  return Object.assign({}, crm, layer, project);
}

function createCrmCustomerOptInByAddresseMutationAttributes(context: IContext, customer: CrmCustomers, address: PhysicalAddresses | ElectronicAddresses) {
  return {
    // required
    addressKeyRef: 'ref:' + createRefKey(context, address),
    status: resolveCodeByReference(context, 'OptInStatus', address.authorizationStatus),
    //optional
    byCustomer: address.authorizationByCustomer,
    // communicationKeyRef: resolveCrmCommunicationByReference(address.authorizationCommunication?.globalKey), // Not supported due to import order
    declineReason: address.authorizationDeclineReason
  };
}

// optIn by channel

function createCustomerOptInsByChannelsMutationAttributes(context: IContext, customer: CrmCustomers) {
  return customer?.addressChannelOptIns?.map(addressChannelOptIn => createCustomerOptInsByChannelMutationAttributes(context, customer, addressChannelOptIn));
}

function createCustomerOptInsByChannelMutationAttributes(context: IContext, customer: CrmCustomers, addressChannelOptIn: AddressChannelOptIn) {
  var crm = createCrmCustomerOptInsByChannelMutationAttributes(context, customer, addressChannelOptIn);
  var layer = {} // Not supported
  var project = {} // Not supported
  return Object.assign({}, crm, layer, project);
}

function createCrmCustomerOptInsByChannelMutationAttributes(context: IContext, customer: CrmCustomers, addressChannelOptIn: AddressChannelOptIn) {
  return {
    // required
    channel: resolveCodeByReference(context, 'AddressChannel', addressChannelOptIn.channel),
    status: resolveCodeByReference(context, 'OptInStatus', addressChannelOptIn.status)
    // optional
    // byCustomer: null, // Not supported
    // communicationKeyRef: resolveCrmCommunicationByReference(address.authorizationCommunication?.globalKey), // Not supported due to import order
    // declineReason: null // Not supported
  };
}

function createCustomerOptInByTopicsMutationAttributes(context: IContext, customer: CrmCustomers) {
  // not supported yet
  return [];
}

// customer score

function handleCustomerScore(context: IContext, customerScore: CustomerScore) {
  if (!customerScore) {
    return null;
  }
  const score = resolveCodeByReference(context, 'CustomerScore', customerScore.type);
  if (!score) {
    return null;
  }
  return { score: score, value: customerScore.value };
}

// electronic address

function createCustomerElectronicAddressMutationAttributes(context: IContext, address: ElectronicAddresses, customer: CrmCustomers, customerRef: string) {
  var crm = createCrmCustomerElectronicAddressMutationAttributes(context, address, customer, customerRef);
  var layer = createLayerCustomerElectronicAddressMutationAttributes(context, address, customer, customerRef);
  var project = createProjectCustomerElectronicAddressMutationAttributes(context, address, customer, customerRef);
  return Object.assign({}, crm, layer, project);
}

function createCrmCustomerElectronicAddressMutationAttributes(context: IContext, address: ElectronicAddresses, customer: CrmCustomers, customerRef: string) {
  return {
    // required
    channel: resolveCodeByReference(context, 'AddressChannel', address.channel),
    channelValue: address.value,
    // itemKeyRef: 'ref:' + customerRef, // no ref required for inline mutation
    // optional
    linkedCustomerKeyRef: null, // not supported,
    notes: address.notes,
    preferred: address.preferred,
    usages: address.usages.map(a => resolveCodeByReference(context, 'AddressUsage', a)).filter(Boolean),
    validFrom: timeShift(context, address.validityFrom,),
    validTo: timeShift(context, address.validityTo),
    mutationRef: createRefKey(context, address)
  };
}

// physical address

function createCustomerPhysicalAddressMutationAttributes(context: IContext, address: PhysicalAddresses, customer: CrmCustomers, customerRef: string) {
  var crm = createCrmCustomerPhysicalAddressMutationAttributes(context, address, customer, customerRef);
  var layer = createLayerCustomerPhysicalAddressMutationAttributes(context, address, customer, customerRef);
  var project = createProjectCustomerPhysicalAddressMutationAttributes(context, address, customer, customerRef);
  return Object.assign({}, crm, layer, project);
}

function createCrmCustomerPhysicalAddressMutationAttributes(context: IContext, address: PhysicalAddresses, customer: CrmCustomers, customerRef: string) {
  return {
    // required
    channel: resolveCodeByReference(context, 'AddressChannel', address.channel),
    // itemKeyRef: 'ref:' + customerRef, // no ref required for inline mutation
    // optional
    additionalLine1: address.additionalLine1,
    additionalLine2: address.additionalLine2,
    city: address.city,
    country: address.country.isoCode, // iso-code is supported as well
    linkedCustomerKeyRef: resolveCrmCustomerByReference(context, address.referencedCustomer.globalKey), // may reference a customer not yet imported
    // masterAddressKeyRef: null, // not supported
    notes: address.notes,
    poBox: address.poBoxNumber,
    poBoxName: address.poBox,
    preferred: address.preferred,
    // recipientOverride: null, // not supported
    street: address.street,
    usages: address.usages.map(a => resolveCodeByReference(context, 'AddressUsage', a)).filter(Boolean),
    validFrom: timeShift(context, address.validityFrom),
    validTo: timeShift(context, address.validityTo),
    zipCode: address.zipCode,
    mutationRef: createRefKey(context, address)
  };
}

// customer interest

function handleCustomerInterest(context: IContext, interest: CustomerInterest, customer: CrmCustomers, customerRef: string) {
  return ProcessorTypes.dataMutation.createModifyCustomerInterest(createCustomerInterestMutationAttributes(context, interest, customer, customerRef));
}

function createCustomerInterestMutationAttributes(context: IContext, interest: CustomerInterest, customer: CrmCustomers, customerRef: string) {
  var crm = createCrmCustomerInterestMutationAttributes(context, interest, customer, customerRef);
  var layer = createLayerCustomerInterestMutationAttributes(context, interest, customer, customerRef);
  var project = createProjectCustomerInterestMutationAttributes(context, interest, customer, customerRef);
  return Object.assign({}, crm, layer, project);
}

function createCrmCustomerInterestMutationAttributes(context: IContext, interest: CustomerInterest, customer: CrmCustomers, customerRef: string) {
  return {
    customerKeyRef: 'ref:' + customerRef,
    quantity: interest.quantity,
    requestedBy: resolveCodeByReference(context, 'CustomerInterestRequestedBy', interest.requestedBy),
    status: resolveCodeByReference(context, 'CustomerInterestStatus', interest.status),
    type: resolveCodeByReference(context, 'CustomerInterest', interest.type)
  };
}

// user

function handleUser(context: IContext, user: User, userCustomer: CrmCustomers, customerRef: string) {
  return Mutations.create('CrmUserCreate', createUserMutationAttributes(context, user, userCustomer, customerRef));
}

function createUserMutationAttributes(context: IContext, user: User, userCustomer: CrmCustomers, customerRef: string) {
  var crm = createCrmUserMutationAttributes(context, user, userCustomer, customerRef);
  var layer = createLayerUserMutationAttributes(context, user, userCustomer, customerRef);
  var project = createProjectUserMutationAttributes(context, user, userCustomer, customerRef);
  return Object.assign({}, crm, layer, project);
