import { Self } from './definition';
import { Invocation } from '../interface';
import { ProcessorTypes } from '@eip/core';
import { createRefKey, resolveCodeByReference, resolveCrmBusinessByReference, resolveCrmCustomerByReference, resolveResponsibleKey } from '../../scripts/helper';
import { handleDocument } from '../../scripts/crm_import';
import { createLayerTaskMutationAttributes } from '../../scripts/layer_import';
import { createProjectTaskMutationAttributes } from '../../scripts/project_import';
import { CrmTasks, IContext } from '../../scripts/data_types';
import { timeShift } from '../../scripts/timeshift';

export function process(invocation: Invocation, self: Self) {
  const mutations = [];
  const context: IContext = invocation.processors.createTask.input.context;
  const task: CrmTasks = invocation.processors.createTask.input.task;

  // task
  mutations.push(handleTask(context, task));

  // documents
  task.documents.map(d => handleDocument(context, task.id, d.globalKey)).filter(Boolean).forEach(m => mutations.push(m));

  if (mutations.filter(Boolean).length > 0) {
      self.withOutlet('hasMutations');
  }
  else {
    self.withOutlet('noMutations');
  }
  return mutations.filter(Boolean);
}

function handleTask(context: IContext, task: CrmTasks) {
  return ProcessorTypes.dataMutation.createModifyTask(createTaskMutationAttributes(context, task));
}

function createTaskMutationAttributes(context: IContext, task: CrmTasks) {
  var crm = createCrmTaskMutationAttributes(context, task);
  var layer = createLayerTaskMutationAttributes(context, task);
  var project = createProjectTaskMutationAttributes(context, task);
  return Object.assign({}, crm, layer, project);
}

function createCrmTaskMutationAttributes(context: IContext, task: CrmTasks) {
  return {
    subject: task.subject,
    dueDate: timeShift(context, task.dueDate),
    doneDate: timeShift(context, task.doneDate),
    highPriority: task.highPriority,
    partitions: task.partitions.map(p => resolveCodeByReference(context, 'Partition', p)),
    primaryCustomer: task.primaryCustomer ? resolveCrmCustomerByReference(context, task.primaryCustomer.globalKey) : null,
    // contextCustomer: null, // 401880: do not provide null value to avoid error in log
    responsible: resolveResponsibleKey(context, task.responsible),
    business: task.business ? resolveCrmBusinessByReference(context, task.business.globalKey) : null,
    remark: task.remark,
    reference: createRefKey(context, task)
  };
}

