import { ProcessorTypes } from '@eip/core';
import { Codes } from '@eip/crm-core';
import { Mutations } from '@eip/crm-mutation';
import { createLayerBusinessDeliveryMutationAttributes, createLayerBusinessMutationAttributes, createLayerBusinessPaymentMutationAttributes, createLayerBusinessProductMutationAttributes, createLayerBusinessRoleMutationAttributes } from '../../scripts/layer_import';
import { createProjectBusinessDeliveryMutationAttributes, createProjectBusinessMutationAttributes, createProjectBusinessPaymentMutationAttributes, createProjectBusinessProductMutationAttributes, createProjectBusinessRoleMutationAttributes } from '../../scripts/project_import';
import { createRefKey, resolveCodeByReference, resolveCrmBusinessByReference, resolveCrmCustomerByReference, resolveCrmUserByReference, resolveImportedReference, validateCurrencyAmount } from '../../scripts/helper';
import { handleDocument } from '../../scripts/crm_import';
import { timeShift } from '../../scripts/timeshift';
export function process(invocation, self) {
    const mutations = [];
    const context = invocation.processors.createBusiness.input.context;
    const business = invocation.processors.createBusiness.input.business;
    // business
    mutations.push(handleBusiness(context, business));
    const businessRef = createRefKey(context, business);
    // business roles
    business.businessRoles?.map(r => handleBusinessRole(context, r, businessRef)).filter(Boolean).forEach(r => mutations.push(r));
    // business products
    business.businessProducts?.map(r => handleBusinessProduct(context, r, businessRef)).filter(Boolean).forEach(r => mutations.push(r));
    // business delivery
    business.businessDeliveries?.map(d => handleBusinessDelivery(context, d, businessRef)).filter(Boolean).forEach(r => mutations.push(r));
    // business status
    business.businessStatus?.map(s => handleBusinessStatus(context, s, businessRef)).filter(Boolean).forEach(r => mutations.push(r));
    // business payments
    business.payments?.map(p => handleBusinessPayment(context, p, businessRef)).filter(Boolean).forEach(r => mutations.push(r));
    // business payment documents
    business.payments?.forEach(p => p.documents?.map(pd => handleDocument(context, p.id, pd.globalKey)).filter(Boolean).forEach(r => mutations.push(r)));
    // business documents
    business.documents.map(d => handleDocument(context, businessRef, d.globalKey)).filter(Boolean).forEach(m => mutations.push(m));
    if (mutations.filter(Boolean).length > 0) {
        self.withOutlet('hasMutations');
    }
    else {
        self.withOutlet('noMutations');
    }
    return mutations.filter(Boolean);
}
// business
function handleBusiness(context, business) {
    return Mutations.create('CrmBusinessImport', createBusinessMutationAttributes(context, business));
}
function createBusinessMutationAttributes(context, business) {
    var crm = createCrmBusinessMutationAttributes(context, business);
    var layer = createLayerBusinessMutationAttributes(context, business);
    var project = createProjectBusinessMutationAttributes(context, business);
    return Object.assign({}, crm, layer, project);
}
function createCrmBusinessMutationAttributes(context, business) {
    return {
        // mandatory
        customerKeyRef: resolveCrmCustomerByReference(context, business.customer?.globalKey),
        netPrice: business.netPrice?.amount,
        probabilityOwn: resolveCodeByReference(context, 'BusinessProbability', business.probabilityOwn),
        probabilityRealisation: resolveCodeByReference(context, 'BusinessProbability', business.probabilityRealisation),
        startDate: timeShift(context, business.startDate),
        subject: business.subject,
        type: resolveCodeByReference(context, 'BusinessType', business.type),
        // optional
        businessNo: business.businessNo,
        currency: resolveCodeByReference(context, 'Currency', business.currency),
        endDate: timeShift(context, business.endDate),
        followUpDate: timeShift(context, business.followUpDate),
        linkedBusinessKeyRef: resolveCrmBusinessByReference(context, business.linkedBusiness?.globalKey),
        notes: business.notes,
        partitions: business.partitions.map(p => resolveCodeByReference(context, 'Partition', p)),
        pricePaymentFrequency: resolveCodeByReference(context, 'BusinessPrice', business.pricePaymentFrequency),
        projectManagerUserKeyRef: resolveCrmUserByReference(context, business.projectManager?.user.globalKey),
        projectManagerTeam: resolveCodeByReference(context, 'Team', business.projectManager?.team?.team),
        projectManagerTeamRole: resolveCodeByReference(context, 'TeamRole', business.projectManager?.teamRole),
        reasonLost: resolveCodeByReference(context, 'BusinessReasonLost', business.reasonLost),
        salesManagerUserKeyRef: resolveCrmUserByReference(context, business.salesManager?.user?.globalKey),
        salesManagerTeam: resolveCodeByReference(context, 'Team', business.salesManager?.team?.team),
        salesManagerTeamRole: resolveCodeByReference(context, 'TeamRole', business.salesManager?.teamRole),
        status: resolveCodeByReference(context, 'BusinessStatus', business.status),
        vatPercent: business.vatPercent ? (business.vatPercent / 100) : null,
        statusHistory: createCrmBusinessStatusHistoriesMutationAttributes(context, business),
        mutationRef: createRefKey(context, business)
    };
}
// status history
function createCrmBusinessStatusHistoriesMutationAttributes(context, business) {
    return business.businessStatus?.map(status => createCrmBusinessStatusHistoryMutationAttributes(context, status)).filter(Boolean);
}
function createCrmBusinessStatusHistoryMutationAttributes(context, businessStatus) {
    return {
        status: resolveCodeByReference(context, 'BusinessStatus', businessStatus.status),
        date: timeShift(context, businessStatus.date),
        userKeyRef: resolveCrmUserByReference(context, businessStatus.responsibleUser?.globalKey),
        mutationRef: createRefKey(context, businessStatus)
    };
}
// business role
function handleBusinessRole(context, businessRole, businessRef) {
    const role = resolveCodeByReference(context, 'BusinessRole', businessRole.role);
    if (!role) {
        // role type not mapped or known --> skip
        return null;
    }
    if (role === Codes.BusinessRole.Customer || role === Codes.BusinessRole.ProjectManager || role === Codes.BusinessRole.SalesManager) {
        // no mutations of this roles permitted
        return null;
    }
    return ProcessorTypes.dataMutation.createModifyBusinessRole(createBusinessRoleMutationAttributes(context, businessRole, businessRef));
}
function createBusinessRoleMutationAttributes(context, businessRole, businessRef) {
    var crm = createCrmBusinessRoleMutationAttributes(context, businessRole, businessRef);
    var layer = createLayerBusinessRoleMutationAttributes(context, businessRole, businessRef);
    var project = createProjectBusinessRoleMutationAttributes(context, businessRole, businessRef);
    return Object.assign({}, crm, layer, project);
}
function createCrmBusinessRoleMutationAttributes(context, businessRole, businessRef) {
    const roleMutationAttributes = {
        businessRef: 'ref:' + businessRef,
        businessRole: resolveCodeByReference(context, 'BusinessRole', businessRole.role),
        addressRef: resolveImportedReference(context, businessRole.electronicAddress.globalKey ? businessRole.electronicAddress.globalKey : businessRole.physicalAddress.globalKey),
        bankConnectionRef: null,
        validFrom: null,
        validTo: null,
        reference: createRefKey(context, businessRole.role, businessRef + '_role')
    };
    // customer mode
    var roleAssigneMutationAttributes;
    if (businessRole.customer.globalKey) {
        roleAssigneMutationAttributes = {
            customerRef: resolveCrmCustomerByReference(context, businessRole.customer.globalKey)
        };
    }
    else {
        roleAssigneMutationAttributes = {
            team: resolveCodeByReference(context, 'Team', businessRole.responsible.team.team),
            teamRole: resolveCodeByReference(context, 'TeamRole', businessRole.responsible.teamRole)
        };
    }
    return Object.assign({}, roleMutationAttributes, roleAssigneMutationAttributes);
}
// busines product
function handleBusinessProduct(context, businessProduct, businessRef) {
    return ProcessorTypes.dataMutation.createModifyBusinessProduct(createBusinessProductMutationAttributes(context, businessProduct, businessRef));
}
function createBusinessProductMutationAttributes(context, businessProduct, businessRef) {
    var crm = createCrmBusinessProductMutationAttributes(context, businessProduct, businessRef);
    var layer = createLayerBusinessProductMutationAttributes(context, businessProduct, businessRef);
    var project = createProjectBusinessProductMutationAttributes(context, businessProduct, businessRef);
    return Object.assign({}, crm, layer, project);
}
function createCrmBusinessProductMutationAttributes(context, businessProduct, businessRef) {
    return {
        business: 'ref:' + businessRef,
        code: resolveCodeByReference(context, 'BusinessProduct', businessProduct.code),
        discountPercent: businessProduct.discountPercent,
        finalPrice: businessProduct.finalPrice,
        quantity: businessProduct.quantity,
        reference: createRefKey(context, businessProduct.code, businessRef + '_product')
    };
}
// business delivery
function handleBusinessDelivery(context, businessDelivery, businessRef) {
    return Mutations.create('CrmDeliveryCreate', createBusinessDeliveryMutationAttributes(context, businessDelivery, businessRef));
}
function createBusinessDeliveryMutationAttributes(context, businessDelivery, businessRef) {
    var crm = createCrmBusinessDeliveryMutationAttributes(context, businessDelivery, businessRef);
    var layer = createLayerBusinessDeliveryMutationAttributes(context, businessDelivery, businessRef);
    var project = createProjectBusinessDeliveryMutationAttributes(context, businessDelivery, businessRef);
    return Object.assign({}, crm, layer, project);
}
function createCrmBusinessDeliveryMutationAttributes(context, businessDelivery, businessRef) {
    return {
        // mandatory
        businessKeyRef: 'ref:' + businessRef,
        subject: businessDelivery.name,
        netPrice: businessDelivery.netPrice?.amount,
        // optional
        deliveredOn: timeShift(context, businessDelivery.actual),
        notes: businessDelivery.notes,
        plannedFor: timeShift(context, businessDelivery.planned),
        mutationRef: createRefKey(context, businessDelivery)
    };
}
// business payment
function handleBusinessPayment(context, businessPayment, businessRef) {
    return ProcessorTypes.dataMutation.createModifyPayment(createBusinessPaymentMutationAttributes(context, businessPayment, businessRef));
}
function createBusinessPaymentMutationAttributes(context, businessPayment, businessRef) {
    var crm = createCrmBusinessPaymentMutationAttributes(context, businessPayment, businessRef);
    var layer = createLayerBusinessPaymentMutationAttributes(context, businessPayment, businessRef);
    var project = createProjectBusinessPaymentMutationAttributes(context, businessPayment, businessRef);
    return Object.assign({}, crm, layer, project);
}
function createCrmBusinessPaymentMutationAttributes(context, businessPayment, businessRef) {
    return {
        //amount: toMutationCurrencyAmount(businessPayment.amount), // TODO check usage
        billingType: resolveCodeByReference(context, 'PaymentType', businessPayment.billingType),
        business: 'ref:' + businessRef,
        customer: resolveCrmCustomerByReference(context, businessPayment.customer?.globalKey),
        date: timeShift(context, businessPayment.date),
        // id, // not used
        invoiceAmount: validateCurrencyAmount(context, businessPayment.invoiceAmount),
        invoiceDate: timeShift(context, businessPayment.invoiceDate),
        invoiceNo: businessPayment.invoiceNo,
        paymentNo: businessPayment.paymentNo,
        reference: businessPayment.id,
