export function process(invocation: Invocation, self: Self) {
  const currentCustomerType = invocation.processors.iterationCustomerTypes.element;
  LOG.info('Processing customer type {}.', currentCustomerType);

  // internal person
  if (currentCustomerType?.value?.globalKey === '6ac52067-e78f-47dd-96a6-08b7f80507ce') {
    // // internal person are processed with only one iteration worker to avoid ACL calc deadlocks
    self.withOutlet('internalPerson');
  }
  else {
    self.withOutlet('default');
  }

  return Collections
    .get('customers_crm')
    .list({
      valueRestrictions: buildValueRestriction(currentCustomerType?.value)
    });
}

function buildValueRestriction(customerType: CodeRef) {
    const filterBuilder = (codeRelation: string, globalKey: string, operation: 'eq' | 'ne' = 'eq') => Collections
    .jsonPath()
    .property(codeRelation)
    .condition(b => {
      const op = operation === 'eq' ? b.eq : b.ne;
      return op(b.filterPath().property('globalKey'), globalKey);
    });

  const allOtherCustomerTypes = 'ALL_OTHER_CUSTOMER_TYPES';
  if (customerType.globalKey === allOtherCustomerTypes) {
    return Collections.get('metadata_customerTypeImportOrder').list()
      .map(t => t.value)
      .filter(c => c.globalKey != allOtherCustomerTypes)
      .map(c => filterBuilder('type', c.globalKey, 'ne'));
  }
  return [filterBuilder('type', customerType.globalKey)];
}

