import { Self } from './definition';
import { Invocation } from '../interface';
import { LOG, ProcessorTypes } from '@eip/core';
import { Codes } from '@eip/crm-core';
import { Mutations } from '@eip/crm-mutation';
import { BusinessRef, ChatConversation, ChatMessage, CommunicationParticipant, CrmCommunications, CustomerRef, IContext } from '../../scripts/data_types';
import { createRefKey, resolveCodeByReference, resolveCrmBusinessByReference, resolveCrmCustomerByReference, resolveCrmServiceLine, resolveCrmUserByReference } from '../../scripts/helper';
import { handleDocument } from '../../scripts/crm_import';
import { createLayerCommunicationMutationAttributes, createLayerCommunicationParticipantMutationAttributes, createLayerSalesCommunicationMutationAttributes, createLayerServiceCommunicationMutationAttributes } from '../../scripts/layer_import';
import { createProjectChatConversationDefaultMessageChannelAddress, createProjectCommunicationMutationAttributes, createProjectCommunicationParticipantMutationAttributes, createProjectSalesCommunicationMutationAttributes, createProjectServiceCommunicationMutationAttributes } from '../../scripts/project_import';
import { timeShift } from '../../scripts/timeshift';

export function process(invocation: Invocation, self: Self) {
  const mutations = [];
  const context: IContext = invocation.processors.createCommunication.input.context;
  const communication: CrmCommunications = invocation.processors.createCommunication.input.communication;

  // chat conversation
  handleCommunicationChatConversations(context, communication)?.forEach(m => mutations.push(m));

  // communication record
  mutations.push(handleCommunication(context, communication));
  const communicationRef = createRefKey(context, communication);

  if (mutations.filter(Boolean).length > 0) {
    // participants
    communication.communicationParticipants
      .map(cp => handleCommunicationParticipant(context, cp, communicationRef)).filter(Boolean).forEach(m => mutations.push(m));

    // documents
    communication.documents.map(d => handleDocument(context, communicationRef, d.globalKey)).filter(Boolean).forEach(m => mutations.push(m));

    self.withOutlet('hasMutations');
  }
    else {
    self.withOutlet('noMutations');
  }
  return mutations.filter(Boolean);
}

function handleCommunication(context: IContext, communication: CrmCommunications) {
  const type = resolveCodeByReference(context, 'CommunicationType', communication.type);

  if (type === Codes.CommunicationType.Marketing || type === Codes.CommunicationType.Story) {
    // not supported, create fallback contact center communication
    return Mutations.create('CrmServiceCommunicationCreate', createServiceCommunicationMutationAttributes(context, communication));
  }
  else if (type === Codes.CommunicationType.Sales) {
    return Mutations.create('CrmSalesCommunicationCreate', createSalesCommunicationMutationAttributes(context, communication));
  }
  else if (type === Codes.CommunicationType.ContactCenter) {
    return Mutations.create('CrmServiceCommunicationCreate', createServiceCommunicationMutationAttributes(context, communication));
  }
  else if (type === Codes.CommunicationType.Configuration) {
    return Mutations.create('CrmCommunicationCreate', createCommunicationMutationAttributes(context, communication));
  } 
}

// sales communication

function createSalesCommunicationMutationAttributes(context: IContext, communication: CrmCommunications) {
  var crm = createCrmSalesCommunicationMutationAttributes(context, communication);
  var layer = createLayerSalesCommunicationMutationAttributes(context, communication);
  var project = createProjectSalesCommunicationMutationAttributes(context, communication);
  return Object.assign({}, crm, layer, project);
}

function createCrmSalesCommunicationMutationAttributes(context: IContext, communication: CrmCommunications) {
  const mainBusiness = getMainBusiness(context, communication);
  const contextCustomer = getContextCustomer(context, communication);
  const chatConversation = getCommunicationChatConversation(context, communication);  
  return {
      // mandatory
      channel: resolveCodeByReference(context, 'MessageChannel', communication.channel),
      incoming: communication.incoming,
      subject: communication.subject,
      // optional
      businessKeyRef: resolveCrmBusinessByReference(context, mainBusiness?.globalKey),
      contextCustomerKeyRef: resolveCrmCustomerByReference(context, contextCustomer?.globalKey),
      emotion: resolveCodeByReference(context, 'Emotion', communication.emotion),
      endDate: timeShift(context, communication.endDate),
      itemKeyRef: chatConversation ? 'ref:' + createRefKey(context, chatConversation) : null,
      language: resolveCodeByReference(context, 'Language', communication.language),
      location: communication.location,
      outboundPhoneScriptUrl: communication.outboundPhoneScriptUrl,
      partitions: communication.partitions?.map(p => resolveCodeByReference(context, 'Partition', p)),
      primaryCustomerKeyRef: resolveCrmCustomerByReference(context, communication.primaryCustomer?.globalKey),
      reactionGroup: resolveCodeByReference(context, 'CommunicationReactionGroup', communication.reactionGroup),
      remark: communication.remark,
      responsibleTeam: resolveCodeByReference(context, 'Team', communication.responsible?.team?.team),
      responsibleTeamRole: resolveCodeByReference(context, 'TeamRole', communication.responsible?.teamRole),
      responsibleUserKeyRef: resolveCrmUserByReference(context, communication.responsible?.user?.globalKey),
      serviceLineKey: resolveCrmServiceLine(context, communication.serviceLine?.globalKey),
      startDate: timeShift(context, communication.startDate),
      status: resolveCodeByReference(context, 'CommunicationStatus', communication.status),
      mutationRef: createRefKey(context, communication)
  };
}

// service communication

function createServiceCommunicationMutationAttributes(context: IContext, communication: CrmCommunications) {
  var crm = createCrmServiceCommunicationMutationAttributes(context, communication);
  var layer = createLayerServiceCommunicationMutationAttributes(context, communication);
  var project = createProjectServiceCommunicationMutationAttributes(context, communication);
  return Object.assign({}, crm, layer, project);
}

function createCrmServiceCommunicationMutationAttributes(context: IContext, communication: CrmCommunications) {
  const mainBusiness = getMainBusiness(context, communication);
  const contextCustomer = getContextCustomer(context, communication);
  const chatConversation = getCommunicationChatConversation(context, communication);
  return {
      // mandatory
      channel: resolveCodeByReference(context, 'MessageChannel', communication.channel),
      incoming: communication.incoming,
      subject: communication.subject,
      // optional
      businessKeyRef: resolveCrmBusinessByReference(context, mainBusiness?.globalKey),
      caseKeyRef: null, // case relevant communications are importeded with the case import
      contextCustomerKeyRef: resolveCrmCustomerByReference(context, contextCustomer?.globalKey),
      emotion: resolveCodeByReference(context, 'Emotion', communication.emotion),
      endDate: timeShift(context,  communication.endDate),
      itemKeyRef: chatConversation ? 'ref:' + createRefKey(context, chatConversation) : null,      
      language: resolveCodeByReference(context, 'Language', communication.language),
      location: communication.location,
      outboundPhoneScriptUrl: communication.outboundPhoneScriptUrl,
      partitions: communication.partitions?.map(p => resolveCodeByReference(context, 'Partition', p)),
      primaryCustomerKeyRef: resolveCrmCustomerByReference(context, communication.primaryCustomer?.globalKey),
      reactionGroup: resolveCodeByReference(context, 'CommunicationReactionGroup', communication.reactionGroup),
      remark: communication.remark,
      responsibleTeam: resolveCodeByReference(context, 'Team', communication.responsible?.team?.team),
      responsibleTeamRole: resolveCodeByReference(context, 'TeamRole', communication.responsible?.teamRole),
      responsibleUserKeyRef: resolveCrmUserByReference(context, communication.responsible?.user?.globalKey),
      serviceLineKey: resolveCrmServiceLine(context, communication.serviceLine?.globalKey),
      startDate: timeShift(context, communication.startDate),
      status: resolveCodeByReference(context, 'CommunicationStatus', communication.status),
      mutationRef: createRefKey(context, communication)
  };
}

// communication

