      subject: communication.subject,
      // optional
      businessKeyRef: resolveCrmBusinessByReference(context, mainBusiness?.globalKey),
      contextCustomerKeyRef: resolveCrmCustomerByReference(context, contextCustomer?.globalKey),
      emotion: resolveCodeByReference(context, 'Emotion', communication.emotion),
      endDate: timeShift(context, communication.endDate),
      itemKeyRef: chatConversation ? 'ref:' + createRefKey(context, chatConversation) : null,
      language: resolveCodeByReference(context, 'Language', communication.language),
      location: communication.location,
      outboundPhoneScriptUrl: communication.outboundPhoneScriptUrl,
      partitions: communication.partitions?.map(p => resolveCodeByReference(context, 'Partition', p)),
      primaryCustomerKeyRef: resolveCrmCustomerByReference(context, communication.primaryCustomer?.globalKey),
      reactionGroup: resolveCodeByReference(context, 'CommunicationReactionGroup', communication.reactionGroup),
      remark: communication.remark,
      responsibleTeam: resolveCodeByReference(context, 'Team', communication.responsible?.team?.team),
      responsibleTeamRole: resolveCodeByReference(context, 'TeamRole', communication.responsible?.teamRole),
      responsibleUserKeyRef: resolveCrmUserByReference(context, communication.responsible?.user?.globalKey),
      serviceLineKey: resolveCrmServiceLine(context, communication.serviceLine?.globalKey),
      startDate: timeShift(context, communication.startDate),
      status: resolveCodeByReference(context, 'CommunicationStatus', communication.status),
      mutationRef: createRefKey(context, communication)
  };
}

// communication participant

function handleCommunicationParticipant(context: IContext, participant: CommunicationParticipant, communicationRef: string) {
  const role = resolveCodeByReference(context, 'CommunicationRole', participant.role);
  if (role === Codes.CommunicationRole.Customer || role === Codes.CommunicationRole.ContextCustomer || role === Codes.CommunicationRole.Responsible) {
    // no mutations of this roles permitted
    return null;
  }

  return ProcessorTypes.dataMutation.createModifyCommunicationParticipant(createCommunicationParticipantMutationAttributes(context, participant, communicationRef));
}

function createCommunicationParticipantMutationAttributes(context: IContext, participant: CommunicationParticipant, communicationRef: string) {
  var crm = createCrmCommunicationParticipantMutationAttributes(context, participant, communicationRef);
  var layer = createLayerCommunicationParticipantMutationAttributes(context, participant, communicationRef);
  var project = createProjectCommunicationParticipantMutationAttributes(context, participant, communicationRef);
  return Object.assign({}, crm, layer, project);
}

function createCrmCommunicationParticipantMutationAttributes(context: IContext, participant: CommunicationParticipant, communicationRef: string) {
  return {
    communicationRef: 'ref:'+communicationRef,
    communicationRole: resolveCodeByReference(context, 'CommunicationRole', participant.role),
    customerRef: resolveCrmCustomerByReference(context, participant.customer?.globalKey),
    reference: communicationRef+'_participant_'+participant.role?.globalKey,
    toBeInformed: participant.isToBeInformed
    // team not supported
  };
}

// chat conversation

function getCommunicationChatConversation(context: IContext, communication: CrmCommunications): ChatConversation {
  if (!communication.chatConversations || communication.chatConversations.length === 0) {
    return null;
  }
  if (communication.chatConversations?.length > 1) {
    LOG.warn('Communication (globalKey={}) with more than one chat conversation. Importing only first chat conversation.', communication.globalKey);
  }
  return communication.chatConversations[0];
}

function handleCommunicationChatConversations(context: IContext, communication: CrmCommunications) {
  let mutations = [];
  let chatConversation = getCommunicationChatConversation(context, communication);
  mutations.push(handleCommunicationChatConversation(context, communication, chatConversation));
  chatConversation?.chatMessages?.map(chatMessage => mutations.push(handleCommunicationChatMessage(context, communication, chatConversation, chatMessage)));
  return mutations.filter(Boolean);
}

function handleCommunicationChatConversation(context: IContext, communication: CrmCommunications, chatConversation: ChatConversation) {
  if (!chatConversation) {
    return null;
  }
  return Mutations.create('CrmChatConversationCreate', createCrmCommunicationChatConversationMutationAttributes(context, communication, chatConversation));
}

function createCrmCommunicationChatConversationMutationAttributes(context: IContext, communication: CrmCommunications, chatConversation: ChatConversation) {
  return {
    // required
    messageChannel: resolveCodeByReference(context, 'MessageChannel', chatConversation.messageChannel),
    receiverCustomerKeyRef: resolveCrmCustomerByReference(context, chatConversation.customer?.globalKey),
    // optional
    chatConversationId: null, // not supported 
    createdOn: timeShift(context, communication.startDate), // inherited by communication
    inbound: communication.incoming, // inherited by communication
    messageChannelAddress: createProjectChatConversationDefaultMessageChannelAddress(context, chatConversation), // not suppored by export, default by project provided
    responsibleCustomerKeyRef: resolveCrmUserByReference(context, chatConversation.responsible?.user?.globalKey), // only user supported
    serviceLineKey: null, // not supported
    status: resolveCodeByReference(context, 'ChatConversationStatus', chatConversation.status),
    mutationRef: createRefKey(context, chatConversation)
  };
}

function handleCommunicationChatMessage(context: IContext, communication: CrmCommunications, chatConversation: ChatConversation, chatMessage: ChatMessage) {
  if (!chatMessage) {
    return null;
  }
  return Mutations.create('CrmChatMessageCreate', createCrmCommunicationChatMessageMutationAttributes(context, communication, chatConversation, chatMessage));
}

function createCrmCommunicationChatMessageMutationAttributes(context: IContext, communication: CrmCommunications, chatConversation: ChatConversation, chatMessage: ChatMessage) {
  return {
    // required
    chatConversationKeyRef: 'ref:'+createRefKey(context, chatConversation),
    senderCustomerKeyRef: resolveCrmCustomerByReference(context, chatMessage.sender?.customer?.globalKey),
    text: chatMessage.text,
    // optional
    attachment: null, // not supported
    chatMessageId: null, // not supported,
    sentOn: timeShift(context, chatMessage.sent),
    type: resolveCodeByReference(context, 'ChatMessageType', chatMessage.type)
  };
}


// helper

function getMainBusiness(context: IContext, communication: CrmCommunications): BusinessRef {
  const businesses = communication.communicationBusinesses
    .filter(b => resolveCodeByReference(context, 'CommunicationBusinessType', b.type) === Codes.CommunicationBusinessType.MainBusiness)
    .map(b => b.business);

  return businesses.length === 1? businesses[0]: null;
}

function getContextCustomer(context: IContext, communication: CrmCommunications): CustomerRef {
  if (!communication.primaryCustomer || !communication.primaryOrContextCustomer) {
    return null;
  }
  if (communication.primaryCustomer.globalKey !== communication.primaryOrContextCustomer.globalKey) {
    return communication.primaryOrContextCustomer;
  }
  else {
    return null;
  }
}

